@push('scripts')
<script src="{{ asset('dms-reference/pmta-vmta-response.js') }}"></script>
<script>
(() => {
    const root=document.getElementById('pmta-vmta');if(!root)return;const status=document.getElementById('pmta-vmta-status');const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';
    const shouldRejectPmtaResponse=window.AlphaLinkPmtaVmtaResponse?.shouldRejectPmtaResponse??((httpOk,result)=>!httpOk||(result?.success===false&&!Array.isArray(result?.results)));
    const api=async(url,method='GET',body=null)=>{const response=await fetch(url,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:body?JSON.stringify(body):undefined});const result=await response.json().catch(()=>({}));if(shouldRejectPmtaResponse(response.ok,result))throw new Error(result.message||Object.values(result.errors||{}).flat()[0]||'PMTA operation failed.');return result;};
    const announce=(message,tone='info')=>{status.textContent=message;if(window.AlphaLinkToast)window.AlphaLinkToast.show(message,tone);};
    const showSelectionError=async(message,statusMessage=message)=>{status.textContent=statusMessage;if(typeof window.PmtaControls?.alert==='function'){await window.PmtaControls.alert('Oops',message);return;}if(window.AlphaLinkToast)window.AlphaLinkToast.show(message,'warning');};
    const domainInput=document.getElementById('pmta-vmta-domains');const routeToggle=document.getElementById('pmta-vmta-route');routeToggle.addEventListener('change',()=>{domainInput.placeholder=routeToggle.checked?'Domain,route':'Domain';});
    const serverSelectV2=document.getElementById('pmta-vmta-server-v2');const ipSelect=document.getElementById('pmta-vmta-ips');const clearSelectionWarning=(message)=>{if(status.textContent===message)status.textContent='';};
    const clearServerWarning=()=>{if(serverSelectV2.value)clearSelectionWarning('Please select a server.');};
    const clearIpWarning=()=>{if(ipSelect.selectedOptions.length)clearSelectionWarning('Please select at least one IP.');};
    serverSelectV2.addEventListener('change',clearServerWarning);
    ipSelect.addEventListener('change',clearIpWarning);
    if(window.jQuery){window.jQuery(serverSelectV2).on('changed.bs.select',clearServerWarning);window.jQuery(ipSelect).on('changed.bs.select',clearIpWarning);}
    const ask=(title,text,verb)=>typeof window.PmtaControls?.confirm==='function'?window.PmtaControls.confirm(title,text,verb,true):Promise.resolve(window.confirm(`${title}\n\n${text}`));
    const showResults=(results)=>{const table=document.getElementById('pmta-vmta-result');table.replaceChildren();const head=document.createElement('thead');const header=document.createElement('tr');['Server','Result'].forEach((label)=>{const cell=document.createElement('th');cell.textContent=label;header.append(cell);});head.append(header);const body=document.createElement('tbody');(results||[]).forEach((entry)=>{const row=document.createElement('tr');[entry.server,entry.message].forEach((value)=>{const cell=document.createElement('td');cell.textContent=value||'';row.append(cell);});body.append(row);});table.append(head,body);};
    const promptForLines=(label)=>window.PmtaControls.prompt(label,'Enter one value per line');
    let grid=null;
    if(window.jQuery?.fn?.DataTable){const $=window.jQuery;grid=$('#pmta-vmta-table').DataTable({
        ajax:{url:root.dataset.rowsUrl,dataSrc:'data'},dom:'<"dms-table-tools"B>frtip',
        buttons:[{extend:'pageLength'},{text:'<i class="fas fa-sync"></i>',titleAttr:'REFRESH',action:(event,table)=>table.ajax.reload(null,false)},
            {text:'<i class="far fa-square"></i>',titleAttr:'SELECT NONE',action:(event,table)=>table.rows({page:'current'}).deselect()},
            {text:'<i class="far fa-check-square"></i>',titleAttr:'SELECT ALL',action:(event,table)=>table.rows({page:'current'}).select()},
            {text:'<i class="fas fa-trash"></i>',titleAttr:'REMOVE SELECTED',action:async(event,table,node)=>{const ids=table.rows({selected:true}).data().toArray().map((row)=>row.id);if(!ids.length||!await ask('Remove selected VMTA rows?','The selected records will be removed from your AlphaLink list.','Remove'))return;table.buttons(node).disable();try{const result=await api(root.dataset.deleteUrl,'DELETE',{ids});announce(result.message,'success');table.ajax.reload(null,false);}catch(error){announce(error.message,'danger');}finally{table.buttons(node).enable();}}},
            {text:'IDS <i class="fas fa-search"></i>',titleAttr:'SEARCH BY IDS',action:async(event,table)=>{const text=await promptForLines('Search IDs');table.columns().search('');if(text)table.column(1).search([...new Set(text.split(/\r?\n/).map((value)=>value.trim()).filter(Boolean))].join('|'),true,false);table.draw();}},
            {text:'DMN <i class="fas fa-search"></i>',titleAttr:'SEARCH BY DOMAINS',action:async(event,table)=>{const text=await promptForLines('Search domains');table.columns().search('');if(text)table.column(4).search([...new Set(text.split(/\r?\n/).map((value)=>value.trim()).filter(Boolean))].join('|'),true,false);table.draw();}}],
        order:[[1,'desc']],pageLength:50,select:{style:'os',selector:'td:first-child'},rowCallback:(row,data)=>{if(!data.is_active)$(row).find('td').addClass('table-danger');},
        columns:[{data:null,defaultContent:'',orderable:false,searchable:false,className:'select-checkbox'},{title:'#',data:'id'},{title:'NAME',data:'name'},{title:'IP',data:'ip'},{title:'DOMAIN',data:'dns'},{title:'CREATED AT',data:'created_at'}],
    });}
    const restore=async(ipIds)=>{if(!ipIds.length)throw new Error('Select at least one IP.');return api(root.dataset.restoreUrl,'POST',{ip_ids:ipIds});};
    const restoreV2=async(serverId)=>api(root.dataset.restoreV2Url,'POST',{server_id:serverId});
    document.getElementById('pmta-vmta-push-v2').addEventListener('click',async(event)=>{const button=event.currentTarget;button.disabled=true;try{const result=await api(root.dataset.pushRowsUrl,'POST',{server_id:document.getElementById('pmta-vmta-server-v2').value,rows:document.getElementById('pmta-vmta-rows-v2').value});announce(result.message,'success');if(grid)grid.ajax.reload(null,false);}catch(error){announce(error.message,'danger');}finally{button.disabled=false;}});
    document.getElementById('pmta-vmta-reset-v2').addEventListener('click',async(event)=>{const button=event.currentTarget;const serverId=serverSelectV2.value;if(!serverId){await showSelectionError('Please select server','Please select a server.');return;}clearSelectionWarning('Please select a server.');if(!await ask('Reset VMTA on the selected server?','This removes your VMTA configuration file from the selected server.','Reset'))return;const original=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='RESETTING…';try{const result=await restoreV2(serverId);showResults(result.results);announce(result.results.map((row)=>`${row.server}: ${row.message}`).join(' · '),result.success?'success':'danger');if(grid)grid.ajax.reload(null,false);}catch(error){announce(error.message,'danger');}finally{button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=original;}});
    document.getElementById('pmta-vmta-push').addEventListener('click',async(event)=>{const button=event.currentTarget;const ipIds=Array.from(document.getElementById('pmta-vmta-ips').selectedOptions).map((option)=>option.value);const domains=Array.from(new Set(domainInput.value.split(/\r?\n/).map((value)=>value.trim()).filter(Boolean)));if(!ipIds.length){announce('Please select at least one IP.','warning');return;}if(!domains.length){announce('Please enter at least one domain.','warning');return;}button.disabled=true;try{const result=await api(root.dataset.pushUrl,'POST',{ip_ids:ipIds,domains:domains.join('\n'),route:routeToggle.checked,duplicate:document.getElementById('pmta-vmta-duplicate').value});showResults(result.results);announce(result.results.map((row)=>`${row.server}: ${row.message}`).join(' · '),result.success?'success':'danger');if(grid)grid.ajax.reload(null,false);}catch(error){showResults([]);announce(error.message,'danger');}finally{button.disabled=false;}});
    document.getElementById('pmta-vmta-reset').addEventListener('click',async(event)=>{const button=event.currentTarget;const ipIds=Array.from(ipSelect.selectedOptions).map((option)=>option.value);if(!ipIds.length){await showSelectionError('Please select at least one ip','Please select at least one IP.');return;}clearSelectionWarning('Please select at least one IP.');if(!await ask('Reset VMTA on the selected servers?','This removes your VMTA configuration file from each selected server.','Reset'))return;const original=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='RESETTING…';try{const result=await restore(ipIds);showResults(result.results);announce(result.results.map((row)=>`${row.server}: ${row.message}`).join(' · '),result.success?'success':'danger');if(grid)grid.ajax.reload(null,false);}catch(error){announce(error.message,'danger');}finally{button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=original;}});
    const searchDialog=document.getElementById('pmta-vmta-ip-search');document.getElementById('pmta-vmta-search-ips').addEventListener('click',()=>searchDialog.showModal());document.getElementById('pmta-vmta-ip-search-cancel').addEventListener('click',()=>searchDialog.close());document.getElementById('pmta-vmta-ip-search-apply').addEventListener('click',()=>{const terms=document.getElementById('pmta-vmta-ip-search-input').value.split(/\r?\n/).map((v)=>v.trim().toLowerCase()).filter(Boolean);const select=document.getElementById('pmta-vmta-ips');Array.from(select.options).forEach((option)=>{const text=option.textContent.toLowerCase();option.selected=terms.some((term)=>text.includes(term));});select.dispatchEvent(new Event('change',{bubbles:true}));if(window.jQuery?.fn.selectpicker)window.jQuery(select).selectpicker('refresh');searchDialog.close();});
    if(window.jQuery?.fn.selectpicker)window.jQuery('.selectpicker').selectpicker();
})();
</script>
@endpush
